/**
 * Moving notifications safely on Prisma: listing them without reading their content, then
 * re-pinning and re-queuing them only while they are at the version that was listed. Also the
 * version token itself: generated by the primary on every write, stored as given on a replica,
 * and falling back to `updatedAt` on a row written before the column existed.
 *
 * The other tests here mock each Prisma call. These run against a small in-memory `notification`
 * delegate instead, which applies a `WHERE` the way SQL does (three-valued, so `<> v` never matches
 * NULL) and moves `updatedAt` on every write, as `@updatedAt` does. That is what makes "nothing was
 * written" something a test can check rather than assume.
 */

import {
  type BaseNotificationAdapter,
  NotificationActionError,
  type NotificationFilter,
  VintaSendFactory,
} from 'vintasend';
import { beforeEach, describe, expect, it, vi } from 'vitest';

import { PrismaNotificationBackendFactory } from '../index';
import type {
  NotificationPrismaClientInterface,
  PrismaNotificationBackend,
} from '../prisma-notification-backend';
import { NotificationStatusEnum, NotificationTypeEnum } from '../prisma-notification-backend';

type Row = Record<string, unknown> & {
  id: string;
  updatedAt: Date;
  notificationVersion: string | null;
};
type Where = Record<string, unknown>;
/** SQL's three values: a comparison with NULL is neither true nor false. */
type Truth = boolean | null;

const FUTURE = new Date('2999-01-01T00:00:00.000Z');
const V = 4;

function and(values: Truth[]): Truth {
  if (values.includes(false)) return false;
  return values.includes(null) ? null : true;
}

function or(values: Truth[]): Truth {
  if (values.includes(true)) return true;
  return values.includes(null) ? null : false;
}

function not(value: Truth): Truth {
  return value === null ? null : !value;
}

function same(a: unknown, b: unknown): boolean {
  return a instanceof Date && b instanceof Date ? a.getTime() === b.getTime() : a === b;
}

function fieldTruth(value: unknown, condition: unknown): Truth {
  if (condition === null) return value === null;
  if (typeof condition !== 'object' || condition instanceof Date) {
    return value === null || value === undefined ? null : same(value, condition);
  }
  const ops = condition as Record<string, unknown>;
  const results: Truth[] = [];
  for (const [op, operand] of Object.entries(ops)) {
    if (op === 'not' && operand === null) {
      results.push(value !== null);
      continue;
    }
    if (value === null || value === undefined) {
      results.push(null);
      continue;
    }
    if (op === 'not') results.push(!same(value, operand));
    else if (op === 'in') results.push((operand as unknown[]).some((item) => same(value, item)));
    else if (op === 'equals') results.push(same(value, operand));
    else if (op === 'gte') results.push((value as Date) >= (operand as Date));
    else if (op === 'lte') results.push((value as Date) <= (operand as Date));
    else if (op === 'gt') results.push((value as Date) > (operand as Date));
    else if (op === 'mode') continue;
    else throw new Error(`The fake does not know the operator ${op}`);
  }
  return and(results);
}

function truth(row: Row, where: Where): Truth {
  const results: Truth[] = [];
  for (const [key, condition] of Object.entries(where)) {
    if (key === 'AND') {
      results.push(and((condition as Where[]).map((sub) => truth(row, sub))));
    } else if (key === 'OR') {
      results.push(or((condition as Where[]).map((sub) => truth(row, sub))));
    } else if (key === 'NOT') {
      const subs = Array.isArray(condition) ? condition : [condition];
      results.push(and(subs.map((sub) => not(truth(row, sub as Where)))));
    } else {
      results.push(fieldTruth(row[key], condition));
    }
  }
  return and(results);
}

/** The `notification` delegate, holding rows in memory. */
class FakeNotifications {
  readonly rows = new Map<string, Row>();
  private clock = Date.parse('2026-01-01T00:00:00.000Z');
  writes = 0;

  private tick(): Date {
    this.clock += 1;
    return new Date(this.clock);
  }

  /**
   * Insert a row as it would be found in the table. It has a token of its own unless `fields` says
   * otherwise; `notificationVersion: null` is a row written before the column existed.
   */
  seed(fields: Record<string, unknown>): string {
    const id = (fields.id as string | undefined) ?? String(this.rows.size + 1).padStart(3, '0');
    this.rows.set(id, {
      userId: 'user-1',
      emailOrPhone: null,
      firstName: null,
      lastName: null,
      notificationType: NotificationTypeEnum.EMAIL,
      title: 'Hi',
      bodyTemplate: 'welcome',
      contextName: 'testContext',
      contextParameters: {},
      sendAfter: null,
      subjectTemplate: null,
      status: NotificationStatusEnum.PENDING_SEND,
      contextUsed: null,
      extraParams: null,
      tenant: null,
      adapterUsed: null,
      sentAt: null,
      readAt: null,
      gitCommitSha: null,
      requestedTemplateVersion: null,
      usedTemplateVersion: null,
      notificationVersion: `seeded-${id}`,
      createdAt: new Date(this.clock),
      updatedAt: this.tick(),
      ...fields,
      id,
    });
    return id;
  }

  private insert(data: Record<string, unknown>): Row {
    const { user, ...fields } = data as { user?: { connect?: { id: unknown } } };
    const id = this.seed({
      ...fields,
      userId: user?.connect?.id ?? (fields as { userId?: unknown }).userId ?? null,
    });
    this.writes += 1;
    return this.snapshot(id);
  }

  create = vi.fn(async ({ data }: { data: Record<string, unknown> }) => ({
    ...this.insert(data),
    attachments: [],
  }));

  createManyAndReturn = vi.fn(async ({ data }: { data: Record<string, unknown>[] }) =>
    data.map((item) => this.insert(item)),
  );

  snapshot(id: string): Row {
    return { ...(this.rows.get(id) as Row) };
  }

  update = vi.fn(async ({ where, data }: { where: Where; data: Record<string, unknown> }) => {
    const row = this.rows.get(where.id as string);
    if (!row || truth(row, where) !== true) {
      throw Object.assign(new Error('No record was found for an update.'), { code: 'P2025' });
    }
    Object.assign(row, data, { updatedAt: this.tick() });
    this.writes += 1;
    return { ...row, attachments: [] };
  });

  findUnique = vi.fn(async ({ where }: { where: Where }) => {
    const row = this.rows.get(where.id as string);
    return row && truth(row, where) === true ? { ...row, attachments: [] } : null;
  });

  findMany = vi.fn(
    async (args: {
      where?: Where;
      select?: Record<string, true>;
      orderBy?: Record<string, 'asc' | 'desc'>;
      skip?: number;
      take?: number;
    }) => {
      const matched = [...this.rows.values()]
        .filter((row) => truth(row, args.where ?? {}) === true)
        .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
      const page = matched.slice(args.skip ?? 0, (args.skip ?? 0) + (args.take ?? matched.length));
      return page.map((row) =>
        args.select
          ? Object.fromEntries(Object.keys(args.select).map((key) => [key, row[key]]))
          : { ...row },
      );
    },
  );
}

let notifications: FakeNotifications;
let backend: PrismaNotificationBackend<any, any>;
let adapter: { send: ReturnType<typeof vi.fn> } & Record<string, unknown>;

beforeEach(() => {
  notifications = new FakeNotifications();
  const prisma = {
    $transaction: vi.fn(),
    notification: notifications,
  } as unknown as NotificationPrismaClientInterface<string, string>;
  backend = new PrismaNotificationBackendFactory().create(prisma);
  adapter = {
    notificationType: 'EMAIL',
    key: 'test-adapter',
    enqueueNotifications: false,
    send: vi.fn().mockResolvedValue(undefined),
    injectBackend: vi.fn(),
    injectLogger: vi.fn(),
    getTemplateRenderer: () => ({ getLatestTemplateVersion: async () => V }),
    supportsAttachments: false,
  };
});

function makeService(options: { withoutAdapters?: boolean } = {}) {
  return new VintaSendFactory<any>().create({
    adapters: (options.withoutAdapters ? [] : [adapter]) as unknown as BaseNotificationAdapter<
      any,
      any
    >[],
    backend,
    logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn() },
    contextGeneratorsMap: { testContext: { generate: async () => ({}) } },
    options: { raiseErrorOnFailedSend: false },
  });
}

async function expectActionError(promise: Promise<unknown>, reason: string) {
  const error = await promise.then(
    () => {
      throw new Error('expected the call to throw');
    },
    (thrown: unknown) => thrown,
  );
  expect(error).toBeInstanceOf(NotificationActionError);
  expect((error as NotificationActionError).reason).toBe(reason);
  return error as NotificationActionError;
}

/** Pending emails with a send time pinned to another version, and failed ones. */
function movableTo(version: number): NotificationFilter<any> {
  return {
    and: [
      { bodyTemplate: 'welcome' },
      {
        or: [
          {
            and: [
              { status: 'PENDING_SEND', hasSendAfter: true, hasRequestedTemplateVersion: true },
              { not: { requestedTemplateVersion: version } },
            ],
          },
          { status: 'FAILED' },
        ],
      },
    ],
  };
}

describe('filterNotificationVersions', () => {
  it('finds the pending and failed emails to move, and nothing else', async () => {
    const pendingOnOld = notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: 1 });
    notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: V }); // already on V
    notifications.seed({ sendAfter: null, requestedTemplateVersion: 1 }); // no send time
    notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: null }); // unpinned
    const failed = notifications.seed({ status: 'FAILED', requestedTemplateVersion: V });
    notifications.seed({ status: 'FAILED', bodyTemplate: 'reset' }); // another key
    notifications.seed({ status: 'SENT', requestedTemplateVersion: 1 }); // delivered

    const listed = await makeService().filterNotificationVersions(movableTo(V), 0, 50);

    expect(listed).toEqual([
      { id: pendingOnOld, version: `seeded-${pendingOnOld}` },
      { id: failed, version: `seeded-${failed}` },
    ]);
  });

  it('selects id, notificationVersion and updatedAt only, with no include', async () => {
    notifications.seed({ status: 'FAILED' });

    await backend.filterNotificationVersions({ status: 'FAILED' }, 2, 25);

    expect(notifications.findMany).toHaveBeenCalledWith({
      where: { status: 'FAILED' },
      select: { id: true, notificationVersion: true, updatedAt: true },
      orderBy: { id: 'asc' },
      skip: 50,
      take: 25,
    });
  });

  it('pages by id', async () => {
    const ids = [1, 2, 3].map(() => notifications.seed({ status: 'FAILED' }));

    const first = await backend.filterNotificationVersions({ status: 'FAILED' }, 0, 2);
    const second = await backend.filterNotificationVersions({ status: 'FAILED' }, 1, 2);

    expect([...first, ...second].map((entry) => entry.id)).toEqual(ids);
  });
});

describe('presence filters', () => {
  it('tells notifications with a send time from those without, negation included', async () => {
    const scheduled = notifications.seed({ sendAfter: FUTURE });
    const unscheduled = notifications.seed({ sendAfter: null });

    const withTime = await backend.filterNotifications({ hasSendAfter: true }, 0, 10);
    const withoutTime = await backend.filterNotifications({ hasSendAfter: false }, 0, 10);
    const negated = await backend.filterNotifications({ not: { hasSendAfter: true } }, 0, 10);

    expect(withTime.map((n) => n.id)).toEqual([scheduled]);
    expect(withoutTime.map((n) => n.id)).toEqual([unscheduled]);
    expect(negated.map((n) => n.id)).toEqual([unscheduled]);
  });

  it('tells pinned notifications from unpinned ones', async () => {
    const pinned = notifications.seed({ requestedTemplateVersion: 2 });
    const unpinned = notifications.seed({ requestedTemplateVersion: null });

    const yes = await backend.filterNotifications({ hasRequestedTemplateVersion: true }, 0, 10);
    const no = await backend.filterNotifications(
      { not: { hasRequestedTemplateVersion: true } },
      0,
      10,
    );

    expect(yes.map((n) => n.id)).toEqual([pinned]);
    expect(no.map((n) => n.id)).toEqual([unpinned]);
  });

  it('combines with a range on the same column instead of replacing it', async () => {
    const inRange = notifications.seed({ sendAfter: new Date('2030-01-01T00:00:00.000Z') });
    notifications.seed({ sendAfter: FUTURE });
    notifications.seed({ sendAfter: null });

    const found = await backend.filterNotifications(
      { hasSendAfter: true, sendAfterRange: { to: new Date('2031-01-01T00:00:00.000Z') } },
      0,
      10,
    );

    expect(found.map((n) => n.id)).toEqual([inRange]);
  });

  it('reports the new vocabulary and every optional action', async () => {
    const service = makeService();

    expect(await service.getBackendSupportedFilterCapabilities()).toMatchObject({
      'fields.hasSendAfter': true,
      'negation.hasSendAfter': true,
      'fields.hasRequestedTemplateVersion': true,
      'negation.hasRequestedTemplateVersion': true,
      'fields.id': true,
      'negation.id': true,
    });
    expect(await service.getBackendSupportedActionCapabilities()).toEqual({
      'repin.expectedVersion': true,
      'requeue.expectedVersion': true,
      'requeue.templateVersion': true,
      'versions.filter': true,
      'repin.bulk': true,
      'requeue.bulk': true,
    });
  });
});

describe('requeueNotification', () => {
  it('re-pins and re-queues in one conditional UPDATE on the listed version', async () => {
    const id = notifications.seed({ status: 'FAILED', requestedTemplateVersion: 1 });
    const service = makeService({ withoutAdapters: true });
    const [listed] = await service.filterNotificationVersions(movableTo(V), 0, 10);

    const requeued = await service.requeueNotification(id, {
      templateVersion: V,
      expectedVersion: listed?.version,
      send: false,
    });

    expect(notifications.writes).toBe(1);
    expect(notifications.update.mock.calls[0]?.[0]).toMatchObject({
      where: {
        id,
        status: { in: ['FAILED', 'CANCELLED'] },
        AND: [{ notificationVersion: listed?.version }],
      },
      data: { status: 'PENDING_SEND', sentAt: null, requestedTemplateVersion: V },
    });
    expect(requeued).toMatchObject({ status: 'PENDING_SEND', requestedTemplateVersion: V });
    // The write moved the token, so the listed one no longer matches.
    expect(requeued.notificationVersion).not.toBe(listed?.version);
    expect(notifications.snapshot(id).notificationVersion).toBe(requeued.notificationVersion);
  });

  it('refuses CHANGED for a notification written since it was listed, writing nothing', async () => {
    const id = notifications.seed({ status: 'FAILED', requestedTemplateVersion: 1 });
    const [listed] = await backend.filterNotificationVersions(movableTo(V), 0, 10);
    await backend.persistNotificationUpdate(id, { title: 'Edited' } as never);
    const before = notifications.snapshot(id);
    notifications.writes = 0;

    const error = await expectActionError(
      makeService().requeueNotification(id, {
        templateVersion: V,
        expectedVersion: listed?.version,
      }),
      'CHANGED',
    );

    expect(error.message).toBe(
      `Cannot requeue notification ${id}: it changed since the version that was expected`,
    );
    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id)).toEqual(before);
    expect(adapter.send).not.toHaveBeenCalled();
  });

  it('refuses a token the notification is not at, writing nothing', async () => {
    const id = notifications.seed({ status: 'FAILED' });
    const before = notifications.snapshot(id);

    await expectActionError(
      backend.requeueNotification(id, { expectedVersion: 'not-a-version' }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id)).toEqual(before);
  });

  it.each(['PENDING_SEND', 'SENT'])(
    'refuses a %s notification, writing nothing',
    async (status) => {
      const id = notifications.seed({ status, sendAfter: FUTURE });
      const before = notifications.snapshot(id);

      await expectActionError(
        makeService().requeueNotification(id, {
          templateVersion: V,
          expectedVersion: before.notificationVersion as string,
        }),
        'INVALID_STATUS',
      );
      await expect(backend.requeueNotification(id, { templateVersion: V })).rejects.toThrow(
        `in status ${status}`,
      );

      expect(notifications.writes).toBe(0);
      expect(notifications.snapshot(id)).toEqual(before);
    },
  );

  it('refuses a notification a worker sent after the service read it', async () => {
    const id = notifications.seed({ status: 'SENT' });
    const stale = { ...notifications.snapshot(id), status: 'FAILED', attachments: [] };
    notifications.findUnique.mockResolvedValueOnce(stale);

    await expect(makeService().requeueNotification(id, { templateVersion: V })).rejects.toThrow(
      'in status SENT',
    );

    expect(notifications.writes).toBe(0);
    expect(adapter.send).not.toHaveBeenCalled();
  });

  it('returns the notification as the send left it', async () => {
    const sentId = notifications.seed({ status: 'FAILED' });
    const failingId = notifications.seed({ status: 'FAILED' });
    const service = makeService();

    const sent = await service.requeueNotification(sentId);
    adapter.send.mockRejectedValueOnce(new Error('provider down'));
    const failing = await service.requeueNotification(failingId);

    expect(sent.status).toBe('SENT');
    expect(failing.status).toBe('FAILED');
  });
});

describe('repinNotification', () => {
  it('re-pins in one conditional UPDATE on the listed version', async () => {
    const id = notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: 1 });
    const version = notifications.snapshot(id).notificationVersion as string;

    const repinned = await makeService().repinNotification(id, { expectedVersion: version });

    expect(repinned.requestedTemplateVersion).toBe(V);
    expect(notifications.writes).toBe(1);
    expect(notifications.snapshot(id).requestedTemplateVersion).toBe(V);
  });

  it('pins a notification that was not pinned before, which `<> v` alone would miss', async () => {
    const id = notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: null });

    await backend.repinNotification(id, V, {});

    expect(notifications.snapshot(id).requestedTemplateVersion).toBe(V);
  });

  it('refuses CHANGED for a stale version, writing nothing', async () => {
    const id = notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: 1 });
    const listed = notifications.snapshot(id).notificationVersion as string;
    await backend.persistNotificationUpdate(id, { title: 'Edited' } as never);
    const before = notifications.snapshot(id);
    notifications.writes = 0;

    await expectActionError(
      makeService().repinNotification(id, { templateVersion: V, expectedVersion: listed }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id)).toEqual(before);
  });

  it('refuses CHANGED even when the pin already matches', async () => {
    const id = notifications.seed({ requestedTemplateVersion: V });
    const listed = notifications.snapshot(id).notificationVersion as string;
    await backend.persistNotificationUpdate(id, { title: 'Edited' } as never);
    notifications.writes = 0;

    await expectActionError(
      backend.repinNotification(id, V, { expectedVersion: listed }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
  });

  it('writes nothing when the notification is already on that version', async () => {
    const id = notifications.seed({ requestedTemplateVersion: V });
    const version = notifications.snapshot(id).notificationVersion as string;

    const repinned = await backend.repinNotification(id, V, { expectedVersion: version });

    expect(repinned.requestedTemplateVersion).toBe(V);
    expect(notifications.writes).toBe(0);
  });

  it('refuses a notification a worker sent after the service read it, writing nothing', async () => {
    const id = notifications.seed({ status: 'SENT', requestedTemplateVersion: 1 });
    const stale = { ...notifications.snapshot(id), status: 'PENDING_SEND', attachments: [] };
    notifications.findUnique.mockResolvedValueOnce(stale);

    const error = await expectActionError(makeService().repinNotification(id), 'INVALID_STATUS');

    expect(error.status).toBe('SENT');
    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id).requestedTemplateVersion).toBe(1);
  });

  it('refuses a notification that does not exist', async () => {
    await expectActionError(backend.repinNotification('missing', V, {}), 'NOT_FOUND');
  });

  it('rejects a version that is not a non-negative integer before writing', async () => {
    const id = notifications.seed({});

    await expect(backend.repinNotification(id, -1, {})).rejects.toThrow(RangeError);
    expect(notifications.update).not.toHaveBeenCalled();
  });
});

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

const regularInput = {
  userId: 'user-1',
  notificationType: NotificationTypeEnum.EMAIL,
  title: 'Hi',
  bodyTemplate: 'welcome',
  contextName: 'testContext',
  contextParameters: {},
  sendAfter: null,
  subjectTemplate: null,
  extraParams: null,
};

const oneOffInput = {
  emailOrPhone: 'someone@example.com',
  firstName: 'Ana',
  lastName: 'Silva',
  notificationType: NotificationTypeEnum.EMAIL,
  title: 'Hi',
  bodyTemplate: 'welcome',
  contextName: 'testContext',
  contextParameters: {},
  sendAfter: null,
  subjectTemplate: null,
  extraParams: null,
};

/**
 * One write of each kind, run against a row in a status it accepts. `run` passes `options` through
 * and returns the token the write reports: from the notification it returns, or from the
 * `NotificationWriteResult` of a write that returns no notification.
 */
type WriteCase = {
  name: string;
  seed?: Record<string, unknown>;
  run: (id: string, options?: { notificationVersion?: string }) => Promise<string | undefined>;
};

const writeCases: WriteCase[] = [
  {
    name: 'persistNotification',
    run: async (_id, options) =>
      (await backend.persistNotification(regularInput as never, options)).notificationVersion,
  },
  {
    name: 'persistNotificationUpdate',
    seed: {},
    run: async (id, options) =>
      (await backend.persistNotificationUpdate(id, { title: 'Edited' } as never, options))
        .notificationVersion,
  },
  {
    name: 'persistOneOffNotification',
    run: async (_id, options) =>
      (await backend.persistOneOffNotification(oneOffInput as never, options)).notificationVersion,
  },
  {
    name: 'persistOneOffNotificationUpdate',
    seed: { userId: null, emailOrPhone: 'someone@example.com' },
    run: async (id, options) =>
      (await backend.persistOneOffNotificationUpdate(id, { title: 'Edited' } as never, options))
        .notificationVersion,
  },
  {
    name: 'markAsSent',
    seed: {},
    run: async (id, options) => (await backend.markAsSent(id, true, options)).notificationVersion,
  },
  {
    name: 'markAsFailed',
    seed: {},
    run: async (id, options) => (await backend.markAsFailed(id, true, options)).notificationVersion,
  },
  {
    name: 'markAsRead',
    seed: { status: 'SENT' },
    run: async (id, options) => (await backend.markAsRead(id, true, options)).notificationVersion,
  },
  {
    name: 'cancelNotification',
    seed: {},
    run: async (id, options) => (await backend.cancelNotification(id, options)).notificationVersion,
  },
  {
    name: 'storeAdapterAndContextUsed',
    seed: {},
    run: async (id, options) =>
      (await backend.storeAdapterAndContextUsed(id, 'test-adapter', {}, options))
        .notificationVersion,
  },
  {
    name: 'storeTemplateVersion',
    seed: {},
    run: async (id, options) =>
      (await backend.storeTemplateVersion(id, V, options)).notificationVersion,
  },
  {
    name: 'requeueNotification',
    seed: { status: 'FAILED' },
    run: async (id, options) =>
      (await backend.requeueNotification(id, { ...options })).notificationVersion,
  },
  {
    name: 'repinNotification',
    seed: { requestedTemplateVersion: 1 },
    run: async (id, options) =>
      (await backend.repinNotification(id, V, { ...options })).notificationVersion,
  },
];

/** The ID of the row a case wrote: the seeded one, or the one it created. */
async function runCase(
  writeCase: WriteCase,
  options?: { notificationVersion?: string },
): Promise<{ id: string; reported: string | undefined }> {
  const seeded = writeCase.seed ? notifications.seed(writeCase.seed) : undefined;
  const reported = await writeCase.run(seeded ?? '', options);
  const id = seeded ?? [...notifications.rows.keys()].at(-1);
  return { id: id as string, reported };
}

describe('version tokens written by the primary', () => {
  it.each(writeCases.map((writeCase) => [writeCase.name, writeCase] as const))(
    '%s stores a new token when it is given none, and reports it',
    async (_name, writeCase) => {
      const { id, reported } = await runCase(writeCase);

      const stored = notifications.snapshot(id).notificationVersion;
      expect(stored).toMatch(UUID);
      expect(stored).not.toBe(`seeded-${id}`);
      expect(reported).toBe(stored);
    },
  );

  it('generates a different token on every write to the same row', async () => {
    const created = await backend.persistNotification(regularInput as never);
    const id = created.id as string;
    const tokens = [created.notificationVersion];

    tokens.push(
      (await backend.persistNotificationUpdate(id, { title: 'A' } as never)).notificationVersion,
    );
    tokens.push(
      (await backend.storeAdapterAndContextUsed(id, 'test-adapter', {})).notificationVersion,
    );
    tokens.push((await backend.markAsFailed(id, true)).notificationVersion);
    tokens.push((await backend.requeueNotification(id, {})).notificationVersion);
    tokens.push((await backend.markAsSent(id, true)).notificationVersion);
    tokens.push((await backend.markAsRead(id, true)).notificationVersion);

    expect(new Set(tokens).size).toBe(tokens.length);
    expect(notifications.snapshot(id).notificationVersion).toBe(tokens.at(-1));
  });

  it('bulkPersistNotifications gives every notification a token of its own', async () => {
    const ids = await backend.bulkPersistNotifications([regularInput, regularInput] as never);

    const stored = ids.map((id) => notifications.snapshot(id as string).notificationVersion);
    expect(stored[0]).toMatch(UUID);
    expect(stored[1]).toMatch(UUID);
    expect(stored[0]).not.toBe(stored[1]);
  });
});

describe('version tokens copied by a replica', () => {
  it.each(writeCases.map((writeCase) => [writeCase.name, writeCase] as const))(
    '%s stores the token it is given as it is, and reports it',
    async (_name, writeCase) => {
      const { id, reported } = await runCase(writeCase, { notificationVersion: 'from-primary' });

      expect(notifications.snapshot(id).notificationVersion).toBe('from-primary');
      expect(reported).toBe('from-primary');
    },
  );

  it('bulkPersistNotifications reads the tokens by index, generating any left out', async () => {
    const ids = await backend.bulkPersistNotifications(
      [regularInput, regularInput, regularInput] as never,
      { notificationVersions: ['first', undefined, 'third'] },
    );

    const stored = ids.map((id) => notifications.snapshot(id as string).notificationVersion);
    expect(stored[0]).toBe('first');
    expect(stored[1]).toMatch(UUID);
    expect(stored[2]).toBe('third');
  });

  it('applyReplicationSnapshotIfNewer stores the snapshot token on a new row', async () => {
    const snapshot = {
      ...regularInput,
      id: 'replicated',
      status: 'PENDING_SEND',
      notificationVersion: 'from-primary',
      updatedAt: FUTURE,
    };

    expect(await backend.applyReplicationSnapshotIfNewer(snapshot as never)).toEqual({
      applied: true,
    });
    expect(notifications.snapshot('replicated').notificationVersion).toBe('from-primary');
  });

  it('applyReplicationSnapshotIfNewer stores the snapshot token over an older row', async () => {
    const id = notifications.seed({});
    const snapshot = {
      ...backend.serializeNotification(notifications.snapshot(id) as never),
      title: 'Edited on the primary',
      notificationVersion: 'from-primary',
      updatedAt: FUTURE,
    };

    expect(await backend.applyReplicationSnapshotIfNewer(snapshot as never)).toEqual({
      applied: true,
    });
    expect(notifications.snapshot(id)).toMatchObject({
      title: 'Edited on the primary',
      notificationVersion: 'from-primary',
    });
  });

  it('lists the replicated token, which the primary accepts as expectedVersion', async () => {
    // The same write replicated: the primary generated the token, the replica was handed it.
    const primary = notifications;
    const id = primary.seed({ status: 'FAILED', notificationVersion: 'v2' });
    notifications = new FakeNotifications();
    const replica = new PrismaNotificationBackendFactory().create({
      $transaction: vi.fn(),
      notification: notifications,
    } as unknown as NotificationPrismaClientInterface<string, string>);
    notifications.seed({ id, status: 'FAILED', notificationVersion: 'v1' });
    await replica.markAsFailed(id, false, { notificationVersion: 'v2' });

    const [listed] = await replica.filterNotificationVersions({ status: 'FAILED' }, 0, 10);
    expect(listed).toEqual({ id, version: 'v2' });

    notifications = primary;
    const requeued = await backend.requeueNotification(id, { expectedVersion: listed?.version });
    expect(requeued.status).toBe('PENDING_SEND');
  });

  it('refuses a token from a replica that has not caught up with CHANGED, writing nothing', async () => {
    const id = notifications.seed({ status: 'FAILED', notificationVersion: 'v2' });
    const before = notifications.snapshot(id);

    await expectActionError(backend.requeueNotification(id, { expectedVersion: 'v1' }), 'CHANGED');
    await expectActionError(backend.repinNotification(id, V, { expectedVersion: 'v1' }), 'CHANGED');

    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id)).toEqual(before);
  });
});

describe('expectedVersion is checked in the UPDATE itself', () => {
  /** Have another writer change the row just before the next conditional `UPDATE` runs. */
  function writeConcurrentlyBeforeNextUpdate(id: string) {
    const original = notifications.update.getMockImplementation();
    notifications.update.mockImplementationOnce(async (args) => {
      const row = notifications.rows.get(id) as Row;
      row.notificationVersion = 'another-writer';
      row.title = 'Written in between';
      return (original as NonNullable<typeof original>)(args);
    });
  }

  it('refuses a requeue with CHANGED when the row changes after the service read it', async () => {
    const id = notifications.seed({ status: 'FAILED' });
    const [listed] = await backend.filterNotificationVersions({ status: 'FAILED' }, 0, 10);
    writeConcurrentlyBeforeNextUpdate(id);

    await expectActionError(
      makeService().requeueNotification(id, { expectedVersion: listed?.version }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id).status).toBe('FAILED');
    expect(adapter.send).not.toHaveBeenCalled();
  });

  it('refuses a repin with CHANGED when the row changes after the service read it', async () => {
    const id = notifications.seed({ requestedTemplateVersion: 1 });
    const listed = notifications.snapshot(id).notificationVersion as string;
    writeConcurrentlyBeforeNextUpdate(id);

    await expectActionError(
      makeService().repinNotification(id, { templateVersion: V, expectedVersion: listed }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id).requestedTemplateVersion).toBe(1);
  });
});

describe('rows written before the notificationVersion column existed', () => {
  it('reads and lists updatedAt as the token while the column is null', async () => {
    const id = notifications.seed({ status: 'FAILED', notificationVersion: null });
    const legacyToken = notifications.snapshot(id).updatedAt.toISOString();

    const listed = await backend.filterNotificationVersions({ status: 'FAILED' }, 0, 10);
    const read = await backend.getNotification(id, false);

    expect(listed).toEqual([{ id, version: legacyToken }]);
    expect(read?.notificationVersion).toBe(legacyToken);
  });

  it('accepts the updatedAt token in the same UPDATE, and gives the row a token of its own', async () => {
    const id = notifications.seed({ status: 'FAILED', notificationVersion: null });
    const [listed] = await backend.filterNotificationVersions({ status: 'FAILED' }, 0, 10);

    const requeued = await backend.requeueNotification(id, { expectedVersion: listed?.version });

    expect(notifications.update.mock.calls[0]?.[0].where.AND).toEqual([
      {
        OR: [
          { notificationVersion: listed?.version },
          { notificationVersion: null, updatedAt: new Date(listed?.version as string) },
        ],
      },
    ]);
    expect(requeued.status).toBe('PENDING_SEND');
    expect(notifications.snapshot(id).notificationVersion).toMatch(UUID);
  });

  it('refuses the updatedAt token once a write has set the column', async () => {
    const id = notifications.seed({ requestedTemplateVersion: 1, notificationVersion: null });
    const [listed] = await backend.filterNotificationVersions({}, 0, 10);
    await backend.persistNotificationUpdate(id, { title: 'Edited' } as never);
    notifications.writes = 0;

    await expectActionError(
      backend.repinNotification(id, V, { expectedVersion: listed?.version }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
  });

  it('refuses the updatedAt token once updatedAt has moved with the column still null', async () => {
    // A write by a version of this backend that predates the column moves updatedAt only.
    const id = notifications.seed({ status: 'FAILED', notificationVersion: null });
    const [listed] = await backend.filterNotificationVersions({ status: 'FAILED' }, 0, 10);
    (notifications.rows.get(id) as Row).updatedAt = new Date('2026-06-01T00:00:00.000Z');

    await expectActionError(
      backend.requeueNotification(id, { expectedVersion: listed?.version }),
      'CHANGED',
    );

    expect(notifications.writes).toBe(0);
    expect(notifications.snapshot(id).status).toBe('FAILED');
  });
});

describe('the id filter', () => {
  it('recounts just a batch of IDs against a filter', async () => {
    const a = notifications.seed({ status: 'FAILED' });
    const b = notifications.seed({ status: 'FAILED' });
    notifications.seed({ status: 'FAILED' }); // matches, but not in the batch
    const sent = notifications.seed({ status: 'SENT' }); // in the batch only

    const listed = await makeService().filterNotificationVersions(
      { and: [{ status: 'FAILED' }, { id: [a, b, sent] }] },
      0,
      50,
    );

    expect(listed.map((entry) => entry.id)).toEqual([a, b]);
  });

  it('matches one ID, nothing for an empty list, and everything else when negated', async () => {
    const a = notifications.seed({});
    const b = notifications.seed({});
    const service = makeService();

    expect((await service.filterNotificationVersions({ id: a }, 0, 50)).map((e) => e.id)).toEqual([
      a,
    ]);
    expect(await service.filterNotificationVersions({ id: [] }, 0, 50)).toEqual([]);
    expect(
      (await service.filterNotificationVersions({ not: { id: [a] } }, 0, 50)).map((e) => e.id),
    ).toEqual([b]);
  });
});

describe('repinNotifications', () => {
  it('re-pins with one conditional UPDATE per target, reading nothing first', async () => {
    const pending = notifications.seed({ sendAfter: FUTURE, requestedTemplateVersion: 1 });
    const failed = notifications.seed({ status: 'FAILED', requestedTemplateVersion: 1 });
    const service = makeService();
    const targets = await service.filterNotificationVersions(movableTo(V), 0, 50);
    notifications.findMany.mockClear();

    const results = await service.repinNotifications(targets, {
      templateVersion: V,
      filter: movableTo(V),
    });

    expect(results.map((result) => [result.id, result.outcome])).toEqual([
      [pending, 'WRITTEN'],
      [failed, 'WRITTEN'],
    ]);
    expect(notifications.findUnique).not.toHaveBeenCalled();
    expect(notifications.findMany).not.toHaveBeenCalled();
    expect(notifications.update).toHaveBeenCalledTimes(2);
    for (const call of notifications.update.mock.calls) {
      expect((call[0] as { select?: unknown }).select).toEqual({ id: true });
    }
    for (const result of results) {
      expect(notifications.snapshot(result.id as string)).toMatchObject({
        requestedTemplateVersion: V,
        notificationVersion: result.version,
      });
    }
  });

  it('skips, with a reason, what changed, moved out of the filter, was sent or is already pinned', async () => {
    const changed = notifications.seed({ requestedTemplateVersion: 1 });
    const outOfFilter = notifications.seed({ bodyTemplate: 'reset', requestedTemplateVersion: 1 });
    const sent = notifications.seed({ status: 'SENT', requestedTemplateVersion: 1 });
    const alreadyOnV = notifications.seed({ requestedTemplateVersion: V });
    const moves = notifications.seed({ requestedTemplateVersion: 1 });
    const service = makeService();
    const targets = await service.filterNotificationVersions({}, 0, 50);
    await backend.markAsFailed(changed, true); // written after it was listed
    const writes = notifications.writes;

    const results = await service.repinNotifications(
      [...targets, { id: 'does-not-exist', version: 'x' }],
      { templateVersion: V, filter: { bodyTemplate: 'welcome' } },
    );
    const byId = new Map(results.map((result) => [result.id, result]));

    expect(byId.get(changed)?.outcome).toBe('CHANGED');
    expect(byId.get(outOfFilter)?.outcome).toBe('NOT_MATCHED');
    expect(byId.get(sent)).toMatchObject({ outcome: 'INVALID_STATUS', status: 'SENT' });
    expect(byId.get(alreadyOnV)).toMatchObject({
      outcome: 'UNCHANGED',
      version: `seeded-${alreadyOnV}`,
    });
    expect(byId.get(moves)?.outcome).toBe('WRITTEN');
    expect(byId.get('does-not-exist')?.outcome).toBe('NOT_MATCHED');
    expect(notifications.writes).toBe(writes + 1);
  });

  it('accepts the legacy updatedAt token of a row written before the column existed', async () => {
    const legacy = notifications.seed({ notificationVersion: null, requestedTemplateVersion: 1 });
    const service = makeService();
    const targets = await service.filterNotificationVersions({ id: legacy }, 0, 50);

    const [result] = await service.repinNotifications(targets, { templateVersion: V });

    expect(result.outcome).toBe('WRITTEN');
  });
});

describe('requeueNotifications', () => {
  it('re-queues failed notifications, re-pinned and rescheduled, and sends nothing', async () => {
    const failed = notifications.seed({
      status: 'FAILED',
      requestedTemplateVersion: 1,
      sentAt: new Date('2026-01-01T00:00:00.000Z'),
    });
    const pending = notifications.seed({ requestedTemplateVersion: 1 });
    const service = makeService();
    const targets = await service.filterNotificationVersions({}, 0, 50);

    const results = await service.requeueNotifications(targets, {
      templateVersion: V,
      sendAfter: FUTURE,
    });
    const byId = new Map(results.map((result) => [result.id, result]));

    expect(byId.get(failed)?.outcome).toBe('WRITTEN');
    expect(byId.get(pending)).toMatchObject({ outcome: 'INVALID_STATUS', status: 'PENDING_SEND' });
    expect(adapter.send).not.toHaveBeenCalled();
    expect(notifications.snapshot(failed)).toMatchObject({
      status: 'PENDING_SEND',
      sentAt: null,
      sendAfter: FUTURE,
      requestedTemplateVersion: V,
      notificationVersion: byId.get(failed)?.version,
    });
  });

  it('keeps the send time when sendAfter is left out', async () => {
    const failed = notifications.seed({ status: 'FAILED', sendAfter: FUTURE });
    const service = makeService();
    const targets = await service.filterNotificationVersions({ id: failed }, 0, 50);

    await service.requeueNotifications(targets);

    expect(notifications.snapshot(failed)).toMatchObject({
      status: 'PENDING_SEND',
      sendAfter: FUTURE,
    });
  });
});
